### UpdateDistribution is called for every resource with detected changes

Source: https://github.com/hashicorp/terraform-provider-aws/blob/main/internal/service/cloudfront/distribution.go

When a plan shows any origin block diff (including spurious response_completion_timeout changes), terraform apply calls UpdateDistribution for THAT resource. There is no mechanism to skip resources that only have attribute-level noise

```go
func resourceDistributionUpdate(ctx context.Context, d *schema.ResourceData, meta any) diag.Diagnostics {
	var diags diag.Diagnostics
	conn := meta.(*conns.AWSClient).CloudFrontClient(ctx)

	if d.HasChangesExcept(names.AttrTags, names.AttrTagsAll) {
		input := cloudfront.UpdateDistributionInput{
			DistributionConfig: expandDistributionConfig(d),
			Id:                 aws.String(d.Id()),
			IfMatch:            aws.String(d.Get("etag").(string)),
		}

		const (
			timeout = 1 * time.Minute
		)
		_, err := tfresource.RetryWhenIsA[any, *awstypes.InvalidViewerCertificate](ctx, timeout, func(ctx context.Context) (any, error) {
			return conn.UpdateDistribution(ctx, &input)
		})

		if errs.IsA[*awstypes.PreconditionFailed](err) {
			var etag string
			etag, err = distroETag(ctx, conn, d.Id())

			if err != nil {
				return sdkdiag.AppendFromErr(diags, err)
			}

			input.IfMatch = aws.String(etag)

			_, err = conn.UpdateDistribution(ctx, &input)
		}

		if err != nil {
			return sdkdiag.AppendErrorf(diags, "updating CloudFront Distribution (%s): %s", d.Id(), err)
		}

		if d.Get("wait_for_deployment").(bool) {
			if _, err := waitDistributionDeployed(ctx, conn, d.Id()); err != nil {
				return sdkdiag.AppendErrorf(diags, "waiting for CloudFront Distribution (%s) deploy: %s", d.Id(), err)
			}
		}
	}

	return append(diags, resourceDistributionRead(ctx, d, meta)...)
}
```

